var n=`1180-caldo-de-res`;var a=`world-1180`;var t=`MX`;var s=`central-america-caribbean`;var o=4;var r=165;var l={en:`Caldo de Res`,ua:`Кальдо де рес`};var g={en:`Caldo de Res is a dish from Mexico prepared with beef shank, beef bones, yellow onion, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кальдо де рес, страва кухні країни Мексика, яку готують із таких продуктів: яловича гомілка, яловичі кістки, жовта цибуля, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 135 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 135 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:135,i:[[`beef-shank`,850,`g`],[`beef-bones`,550,`g`],[`water`,2e3,`ml`],[`yellow-onion`,180,`g`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 23 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 23 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:23,i:[[`potato`,340,`g`],[`carrot`,280,`g`],[`zucchini`,250,`g`],[`white-cabbage`,230,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,30,`g`],[`lime`,2,`pcs`]]}];var m={slug:n,id:a,country:`MX`,region:s,servings:4,minutes:165,title:l,text:g,steps:d};export{t as country,m as default,a as id,r as minutes,s as region,o as servings,n as slug,d as steps,g as text,l as title};